  ],
  "confidence": "high",
  "narrative": "Starting from the post-1990 baseline for a 2/3 majority, updates from opposition consolidation, favorable electoral mechanics, and mixed polling push the odds higher. The resulting calibrated posterior is 89%, with residual uncertainty from turnout dynamics and poll divergence.",
  "justification": {
    "anchor": {
      "probability": 0.44,
      "basis": "Reference class is the post-1990 Hungarian 2/3 majority pattern; anchor probability uses the established base rate (roughly 4/9 elections achieved 133+ seats) yielding about 0.44."
    },
    "factor_updates": [
      {
        "factor": "Opposition consolidation around the Tisza platform",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Major outlets note a unified anti-Orbán vote around Tisza, boosting potential seat share and increasing likelihood of reaching 133+ seats via concentration of votes."
      },
      {
        "factor": "Electoral-system amplification (winner-compensation) boosting seat outcomes from mid-range shares",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Hungary's mixed system can translate mid-range leads into a disproportionate seat gain, elevating odds of a 133+ seat result."
      },
      {
        "factor": "Polling divergence and uncertainty about seat projections",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Conflicting polls dampen confidence and the posterior needs to account for variance across firms."
      },
      {
        "factor": "Turnout volatility and mobilization effects among Tisza supporters",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Motivated opposition base suggests turnout could push seats toward the 133+ threshold."
      },
      {
        "factor": "Economic conditions and public dissatisfaction affecting mobilization",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Economic stress can boost anti-incumbent sentiment, aiding opposition in consolidating votes."
      }
    ],
    "synthesis_rationale": "Starting from a cautious baseline (0.44) and applying multiple independent but correlated updates with strong positive forces (opposition consolidation, electoral amplification) yields a high posterior. The board remains cautious due to poll divergence; however, the structural advantages and momentum justify an elevated probability with a wide credible interval."
  }
}

